#' Multi-Variable Visual Quality
#'
#' 
#' @param data .
#' @param vars .
#' @param check_duplicates .
#' @param check_missing .
#' @param row_level_duplicates .
#' @param plot_data_overview .
#' @param plot_missing_patterns .
#' @param plot_data_types .
#' @param missing_threshold_visual .
#' @param showSummary .
#' @param showRecommendations .
#' @param showExplanations .
#' @param showInteractive .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$overview} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$completeness} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rowMissing} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$duplicates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$duplicatePatterns} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$recommendations} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$explanations} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$scope} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$overviewMap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$missingMap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$typePlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$explorer} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$previewMap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$overview$asDF}
#'
#' \code{as.data.frame(results$overview)}
#'
#' @export
pydataquality <- function(
    data,
    vars = NULL,
    check_duplicates = FALSE,
    check_missing = FALSE,
    row_level_duplicates = FALSE,
    plot_data_overview = FALSE,
    plot_missing_patterns = FALSE,
    plot_data_types = FALSE,
    missing_threshold_visual = 10,
    showSummary = TRUE,
    showRecommendations = TRUE,
    showExplanations = FALSE,
    showInteractive = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydataquality requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- pydataqualityOptions$new(
        vars = vars,
        check_duplicates = check_duplicates,
        check_missing = check_missing,
        row_level_duplicates = row_level_duplicates,
        plot_data_overview = plot_data_overview,
        plot_missing_patterns = plot_missing_patterns,
        plot_data_types = plot_data_types,
        missing_threshold_visual = missing_threshold_visual,
        showSummary = showSummary,
        showRecommendations = showRecommendations,
        showExplanations = showExplanations,
        showInteractive = showInteractive,
        showConsole = showConsole)

    analysis <- pydataqualityClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

